def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1
    opp_coop = n - opp_def
    last_opp = opp[-1]

    if opp_def == 0:
        return 'C'

    if last_opp == 'D':
        if opp_coop > n * 0.8:
            recent = opp[-3:]
            recent_def = 0
            for x in recent:
                if x == 'D':
                    recent_def += 1
            if recent_def <= 1 and rng.random() < 0.1:
                return 'C'
        return 'D'

    if opp_def > n * 0.5:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    if n > 80:
        my_score = 0
        opp_score = 0
        for me, op in history:
            if me == 'C' and op == 'C':
                my_score += 3
                opp_score += 3
            elif me == 'C' and op == 'D':
                opp_score += 5
            elif me == 'D' and op == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1
        if my_score + 10 < opp_score:
            if rng.random() < 0.4:
                return 'D'

    return 'C'
